/** R4 — an ask to a dormant client is Admin, so dormant projects spend the Admin envelope. */
function envelopeOf(p) {
  if (!p) return 'admin';
  var k = String(p.kind || '');
  if (k === 'earning') return 'billable';
  if (k === 'building') return 'building';
  if (k === 'hobby') return 'hobby';
  return 'admin';
}
/**
